t = int(input())
while t != 0:
	n = int(input())
	p = 0
	m = []
	c = [0] * n
	r = [0] * n
	for i in range(n):
		m.append(input())
	for i in range(n - 1, -1, -1):
		for j in range(n - 1, -1, -1):
			if m[i][j] == '#':
				c[j] = 1
				r[i] = 1
			elif c[j] == 0 and r[i] == 0:
				p = p + 1
	print(p)
	t = t - 1
